 const all=[...HW_CITY.map((b,k)=>({b,k,city:1})),{b:[-2,-2,4,4,0],hq:1}].sort((a,c)=>(a.b[0]+a.b[1]+a.b[2]/2+a.b[3]/2)-(c.b[0]+c.b[1]+c.b[2]/2+c.b[3]/2));
 const hq=()=>{let s=`<polygon class="hw-cast" points="${P2([[2,-2,0],[3.4,-1.3,0],[3.4,2.7,0],[2,2,0]])}"/>`+hwBox(-2,-2,4,4,7,{win:1,cls:'hq'});for(let f=0;f<7;f++)s+=`<g class="hw-fb" data-f="${f}"><polygon points="${P2([[-2,2,f+.12],[2,2,f+.12],[2,2,f+.88],[-2,2,f+.88]])}"/><polygon class="r" points="${P2([[2,-2,f+.12],[2,2,f+.12],[2,2,f+.88],[2,-2,f+.88]])}"/></g>`;
  s+=`<g id="hwBeacon"><polyline class="hw-mast" points="${P2([[0,0,7],[0,0,9.2]])}"/><circle cx="${ip(0,0,9.4)[0]}" cy="${ip(0,0,9.4)[1]}" r="7" class="hw-bulb"/><circle cx="${ip(0,0,9.4)[0]}" cy="${ip(0,0,9.4)[1]}" r="28" class="hw-glow"/></g>`;return s};
 const body=all.map(o=>o.hq?hq():`<g class="hw-city" data-k="${o.k}">${hwBox(o.b[0],o.b[1],o.b[2],o.b[3],o.b[4],{win:1})}</g>`).join('');
