let ST=null,TT=null;
function storyInit(){clearTimeout(ST);clearInterval(TT);const S=$('#stage');if(!S)return;
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches,DUR=6500;let cur=-1,paused=false,started=false;
 const scenes=$$('#stage .scn'),tabs=$$('.ana-tabs button');
 const count=(el)=>{const to=+el.dataset.to,suf=el.dataset.suf||'';if(reduce){el.textContent=to.toLocaleString()+suf;return}const t0=performance.now(),d=1300;const f=t=>{const p=Math.min(1,(t-t0)/d),v=Math.round(to*(1-Math.pow(1-p,3)));el.textContent=v.toLocaleString()+suf;if(p<1&&el.isConnected)requestAnimationFrame(f)};requestAnimationFrame(f)};
 const show=i=>{cur=(i+scenes.length)%scenes.length;S.dataset.s=cur;scenes.forEach((s,k)=>{s.classList.toggle('on',k===cur);s.setAttribute('aria-hidden',k===cur?'false':'true')});
  {const tb=$('.ana-tabs');tb.style.setProperty('--i',cur);tb.classList.remove('run');void tb.offsetWidth;if(!reduce&&!paused)tb.classList.add('run')}tabs.forEach((t,k)=>{t.setAttribute('aria-selected',k===cur);t.classList.remove('run');if(k===cur){void t.offsetWidth;if(!reduce&&!paused)t.classList.add('run')}});
  $$('.wbig[data-to]',scenes[cur]).forEach(count);clearTimeout(ST);if(!reduce&&!paused)ST=setTimeout(()=>show(cur+1),DUR)};
 tabs.forEach(t=>t.onclick=()=>show(+t.dataset.i));
 S.onmouseenter=()=>{paused=true;clearTimeout(ST);$('.ana-tabs').classList.add('pause');tabs.forEach(t=>t.classList.add('pause'))};
 S.onmouseleave=()=>{paused=false;$('.ana-tabs').classList.remove('pause');tabs.forEach(t=>t.classList.remove('pause'));show(cur)};
 const names=HOSP.slice(0,8);let n=0;if(!reduce)TT=setInterval(()=>{const t=$('#toastT');if(!t){clearInterval(TT);return}if(cur!==0)return;n=(n+1)%names.length;const w=t.closest('.ntoast');w.classList.remove('ping');void w.offsetWidth;w.classList.add('ping');t.textContent=names[n]},1700);
 const start=()=>{if(started)return;started=true;show(0)};
 if('IntersectionObserver' in window){const o=new IntersectionObserver(es=>{if(es[0].isIntersecting){start();o.disconnect()}},{threshold:.35});o.observe(S)}else start();
}


