/* ---------------- finder search ----------------
   Index + matcher live in ./search.js; this is the glue the hero finder uses. */
let SEARCH_INDEX=null;
export function searchIndex(){
 if(!SEARCH_INDEX)SEARCH_INDEX=buildIndex({TASKS,STEPS,MDAS,HOSP,NEWS,HL,svcNm});
 return SEARCH_INDEX;
}
/** Rebuild the index after changing the underlying data. */
export function resetSearchIndex(){SEARCH_INDEX=null}
/** Search the site. Returns hits in display order, best first. */
export function SEARCH(q,n=8){return groupHits(searchSite(searchIndex(),q,n))}
function renderHits(hits,q,sel){
 let out='',kind=null;
 hits.forEach((h,i)=>{
  if(h.kind!==kind){kind=h.kind;out+=`<li class="fh" role="presentation">${groupTitle(kind)}</li>`}
  out+=`<li role="option" id="fo${i}" aria-selected="${i===sel}" data-i="${i}"><em>${highlight(h.label,q)}</em><span>${h.hint}</span></li>`;
 });
 return out;
}

