const fld=(label,ctrl,o={})=>{const id=o.id;return `<div class="fld${o.cls?' '+o.cls:''}">${o.group?`<span class="lab" id="${id}-l">${label}</span>`:`<label class="lab" for="${id}">${label}${o.opt?'<span class="opt">Optional</span>':''}</label>`}${ctrl}${o.min||o.hint?`<div class="hrow">${o.hint?`<span class="hint" id="${id}-h">${o.hint}</span>`:'<span></span>'}${o.min?`<span class="cnt" aria-hidden="true" data-min="${o.min}">0 / ${o.min}</span>`:''}</div>`:''}${o.err?`<span class="err" id="${id}-e">${mic('err',14)}${o.err}</span>`:''}</div>`};
const chipGroup=(name,id,opts)=>`<div class="chips" role="radiogroup" aria-labelledby="${id}-l" aria-describedby="${id}-e">${opts.map(([v,ic])=>`<label class="chip"><input type="radio" name="${name}" value="${v}" required>${ic?mic(ic,16):''}<span>${v}</span></label>`).join('')}</div>`;
