document.addEventListener('click',e=>{
 const a=e.target.closest('[data-act]');if(a){e.preventDefault();closeMenus();ACT[a.dataset.act]&&ACT[a.dataset.act](a);return}
 const ag=e.target.closest('[data-again]');if(ag){const id=ag.dataset.again;$(`[data-ok="${id}"]`).classList.remove('show');const f=$(`[data-form="${id}"]`);f.reset();f.style.display='';$$('.cnt',f).forEach(c=>{c.textContent='0 / '+c.dataset.min;c.classList.remove('ok')});$$('.invalid',f).forEach(l=>l.classList.remove('invalid'));const q=$('input,select,textarea',f);q&&q.focus();return}
});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();if(f.classList.contains('busy'))return;
 if(!validate(f)){f.classList.remove('shake');void f.offsetWidth;f.classList.add('shake');return}
 const id=f.dataset.form,btn=$('[type=submit]',f),live=$('.mb-live',f),RM=matchMedia('(prefers-reduced-motion: reduce)').matches;f.classList.add('busy');if(btn){btn.disabled=true;btn.setAttribute('aria-busy','true')}if(live)live.textContent='Sending';
 setTimeout(()=>{f.classList.remove('busy');if(btn){btn.disabled=false;btn.removeAttribute('aria-busy')}if(live)live.textContent='';
  const ok=$(`[data-ok="${id}"]`);if(!ok)return;f.style.display='none';ok.classList.add('show');$('.ref',ok).textContent='OTCI-'+Math.random().toString(36).slice(2,8).toUpperCase();ok.focus()},RM?0:800)});
document.addEventListener('input',e=>{const t=e.target;if(t.matches&&t.matches('textarea[data-min]')){const c=t.closest('.fld').querySelector('.cnt');if(c){const n=t.value.trim().length,m=+t.dataset.min;c.textContent=n>=m?`${n} characters`:`${n} / ${m}`;c.classList.toggle('ok',n>=m)}}});
document.addEventListener('change',e=>{const l=e.target.closest&&e.target.closest('.fld.invalid');if(l&&e.target.type==='radio'){l.classList.remove('invalid');$$('input',l).forEach(x=>x.setAttribute('aria-invalid','false'))}});
document.addEventListener('click',e=>{const pw=e.target.closest('[data-pw]');if(pw){const i=pw.parentNode.querySelector('input'),sh=i.type==='password';i.type=sh?'text':'password';pw.textContent=sh?'Hide':'Show';pw.setAttribute('aria-pressed',String(sh));pw.setAttribute('aria-label',sh?'Hide password':'Show password');i.focus();return}
 const cp=e.target.closest('[data-copy]');if(cp){const r=cp.parentNode.querySelector('.ref').textContent;const done=()=>{cp.textContent='Copied';cp.classList.add('ok');setTimeout(()=>{cp.textContent='Copy';cp.classList.remove('ok')},1800)};try{navigator.clipboard.writeText(r).then(done,done)}catch(_){done()}}});
